import{_ as d,o as e,c as a,O as o}from"./chunks/framework.db831a78.js";const b=JSON.parse('{"title":"Go 后端学习笔记","description":"","frontmatter":{},"headers":[],"relativePath":"backend/Go/index.md","filePath":"backend/Go/index.md","lastUpdated":1788941422000}'),r={name:"backend/Go/index.md"};function n(c,t,h,s,l,i){return e(),a("div",null,t[0]||(t[0]=[o(`<h1 id="go-后端学习笔记" tabindex="-1">Go 后端学习笔记 <a class="header-anchor" href="#go-后端学习笔记" aria-label="Permalink to &quot;Go 后端学习笔记&quot;">​</a></h1><blockquote><p>面向 Java / Python 后端工程师的 Go 语言与 Web 后端开发系列，从语法到并发、框架再到工程落地。</p></blockquote><hr><h2 id="一、系列定位" tabindex="-1">一、系列定位 <a class="header-anchor" href="#一、系列定位" aria-label="Permalink to &quot;一、系列定位&quot;">​</a></h2><h3 id="_1-1-这套笔记写给谁" tabindex="-1">1.1 这套笔记写给谁 <a class="header-anchor" href="#_1-1-这套笔记写给谁" aria-label="Permalink to &quot;1.1 这套笔记写给谁&quot;">​</a></h3><p>已有 Java 或 Python 后端基础、希望掌握 Go 并投入 Web 服务开发的工程师。笔记默认你<strong>会一门后端语言</strong>，因此大量使用与 Java / Python 的对照讲解，而不重复解释&quot;什么是循环、什么是数据库&quot;这类通用概念。</p><h3 id="_1-2-内容覆盖总览" tabindex="-1">1.2 内容覆盖总览 <a class="header-anchor" href="#_1-2-内容覆盖总览" aria-label="Permalink to &quot;1.2 内容覆盖总览&quot;">​</a></h3><table><thead><tr><th>模块</th><th>文件</th><th>一句话简介</th><th>难度</th></tr></thead><tbody><tr><td>Go 基础</td><td><a href="./Go-基础">Go-基础.md</a></td><td>环境与 go mod、语法要素、函数、切片 Map、字符串、结构体</td><td>⭐</td></tr><tr><td>Go 进阶特性</td><td><a href="./Go-进阶特性">Go-进阶特性.md</a></td><td>指针、接口、错误处理、反射、泛型、测试与标准库</td><td>⭐⭐</td></tr><tr><td>Go 并发编程</td><td><a href="./Go-并发编程">Go-并发编程.md</a></td><td>goroutine、channel、sync、GMP 调度、并发模式</td><td>⭐⭐⭐</td></tr><tr><td>Go Gin 框架</td><td><a href="./Go-Gin框架">Go-Gin框架.md</a></td><td>路由、参数校验、中间件、JWT、优雅关停、pprof</td><td>⭐⭐</td></tr><tr><td>Go Web 项目实践</td><td><a href="./Go-Web项目实践">Go-Web项目实践.md</a></td><td>分层工程、GORM、Redis 缓存、zap、Docker、生产坑</td><td>⭐⭐⭐</td></tr></tbody></table><h3 id="_1-3-推荐学习路径" tabindex="-1">1.3 推荐学习路径 <a class="header-anchor" href="#_1-3-推荐学习路径" aria-label="Permalink to &quot;1.3 推荐学习路径&quot;">​</a></h3><table><thead><tr><th>阶段</th><th>学习内容</th><th>产出</th></tr></thead><tbody><tr><td>第一阶段：语法入门</td><td>Go-基础</td><td>用 Go 重写一个之前用 Java/Python 写过的小工具</td></tr><tr><td>第二阶段：语言进阶</td><td>Go-进阶特性</td><td>给工具补上错误处理与单元测试</td></tr><tr><td>第三阶段：并发</td><td>Go-并发编程</td><td>手写 worker pool，跑通 <code>go test -race</code></td></tr><tr><td>第四阶段：Web 框架</td><td>Go-Gin框架</td><td>完成带 JWT 鉴权的 REST API</td></tr><tr><td>第五阶段：工程实践</td><td>Go-Web项目实践</td><td>按分层范式搭一个可 Docker 部署的完整服务</td></tr></tbody></table><p>建议顺序阅读：Go-基础 → Go-进阶特性 → Go-并发编程 → Go-Gin框架 → Go-Web项目实践。前两篇可并行，但并发与框架章节依赖前文概念。</p><hr><h2 id="二、java-python-转-go-语法速览" tabindex="-1">二、Java / Python 转 Go：语法速览 <a class="header-anchor" href="#二、java-python-转-go-语法速览" aria-label="Permalink to &quot;二、Java / Python 转 Go：语法速览&quot;">​</a></h2><h3 id="_2-1-变量与常量" tabindex="-1">2.1 变量与常量 <a class="header-anchor" href="#_2-1-变量与常量" aria-label="Permalink to &quot;2.1 变量与常量&quot;">​</a></h3><table><thead><tr><th>场景</th><th>Go</th><th>Java</th><th>Python</th></tr></thead><tbody><tr><td>声明变量</td><td><code>var x int = 1</code> / <code>x := 1</code></td><td><code>int x = 1;</code></td><td><code>x = 1</code></td></tr><tr><td>多返回值</td><td><code>func f() (int, error)</code></td><td>需封装对象或 Optional</td><td>元组解包</td></tr><tr><td>常量</td><td><code>const Max = 100</code></td><td><code>static final</code></td><td>惯例全大写</td></tr><tr><td>枚举</td><td><code>iota</code> + 类型别名</td><td><code>enum</code></td><td><code>IntEnum</code></td></tr><tr><td>类型转换</td><td>显式 <code>int64(x)</code></td><td>显式强转</td><td>隐式随意</td></tr></tbody></table><h3 id="_2-2-流程控制" tabindex="-1">2.2 流程控制 <a class="header-anchor" href="#_2-2-流程控制" aria-label="Permalink to &quot;2.2 流程控制&quot;">​</a></h3><table><thead><tr><th>场景</th><th>Go</th><th>Java</th><th>Python</th></tr></thead><tbody><tr><td>循环</td><td>只有 <code>for</code></td><td><code>for / while / do-while</code></td><td><code>for / while</code></td></tr><tr><td>switch 穿透</td><td>默认不穿透，<code>fallthrough</code> 显式穿透</td><td>默认穿透，<code>break</code> 显式跳出</td><td><code>match-case</code>（3.10+）</td></tr><tr><td>条件带初始化</td><td><code>if err := f(); err != nil</code></td><td>无（可变量提升）</td><td>无</td></tr><tr><td>遍历</td><td><code>for i, v := range xs</code></td><td>增强 for</td><td><code>enumerate</code></td></tr></tbody></table><h3 id="_2-3-对象模型" tabindex="-1">2.3 对象模型 <a class="header-anchor" href="#_2-3-对象模型" aria-label="Permalink to &quot;2.3 对象模型&quot;">​</a></h3><table><thead><tr><th>场景</th><th>Go</th><th>Java</th><th>Python</th></tr></thead><tbody><tr><td>类型定义</td><td><code>type User struct{...}</code></td><td><code>class User</code></td><td><code>class User</code></td></tr><tr><td>方法</td><td>结构体外 <code>func (u *User) M()</code></td><td>类内方法</td><td>类内方法</td></tr><tr><td>继承</td><td>无，结构体内嵌组合</td><td><code>extends</code></td><td>多继承</td></tr><tr><td>可见性</td><td>首字母大小写</td><td>public / private / protected</td><td>下划线约定</td></tr><tr><td>构造</td><td>工厂函数 <code>NewUser()</code></td><td>构造器</td><td><code>__init__</code></td></tr><tr><td>接口</td><td>隐式实现（鸭子类型）</td><td><code>implements</code> 显式</td><td>ABC / Protocol</td></tr><tr><td>泛型</td><td>Go 1.18+ 基础泛型</td><td>成熟泛型体系</td><td>typing（弱）</td></tr></tbody></table><h3 id="_2-4-错误与异常" tabindex="-1">2.4 错误与异常 <a class="header-anchor" href="#_2-4-错误与异常" aria-label="Permalink to &quot;2.4 错误与异常&quot;">​</a></h3><table><thead><tr><th>场景</th><th>Go</th><th>Java</th><th>Python</th></tr></thead><tbody><tr><td>表达方式</td><td>返回值 <code>error</code></td><td>异常抛出</td><td>异常抛出</td></tr><tr><td>处理</td><td><code>if err != nil</code></td><td>try/catch</td><td>try/except</td></tr><tr><td>包装</td><td><code>fmt.Errorf(&quot;...: %w&quot;, err)</code></td><td>cause 链</td><td><code>raise ... from</code></td></tr><tr><td>判断类型</td><td><code>errors.Is / errors.As</code></td><td><code>instanceof</code> / 多 catch</td><td><code>except XxxError</code></td></tr><tr><td>致命错误</td><td><code>panic</code> + <code>recover</code></td><td>未捕获异常</td><td>未捕获异常</td></tr></tbody></table><h3 id="_2-5-并发" tabindex="-1">2.5 并发 <a class="header-anchor" href="#_2-5-并发" aria-label="Permalink to &quot;2.5 并发&quot;">​</a></h3><table><thead><tr><th>场景</th><th>Go</th><th>Java</th><th>Python</th></tr></thead><tbody><tr><td>轻量任务</td><td><code>go func(){...}()</code></td><td>线程 / 虚拟线程(Loom) / 线程池</td><td>协程 asyncio / 线程</td></tr><tr><td>消息传递</td><td>channel</td><td>BlockingQueue</td><td>Queue</td></tr><tr><td>等待完成</td><td>sync.WaitGroup</td><td>CountDownLatch / Future.get</td><td>asyncio.gather</td></tr><tr><td>锁</td><td>sync.Mutex / RWMutex</td><td>synchronized / ReentrantLock</td><td>threading.Lock</td></tr><tr><td>取消传播</td><td>context</td><td>中断 / Future.cancel</td><td>task.cancel</td></tr><tr><td>原子操作</td><td>atomic</td><td>AtomicInteger / volatile</td><td>无（GIL）</td></tr></tbody></table><h3 id="_2-6-工程生态对照" tabindex="-1">2.6 工程生态对照 <a class="header-anchor" href="#_2-6-工程生态对照" aria-label="Permalink to &quot;2.6 工程生态对照&quot;">​</a></h3><table><thead><tr><th>场景</th><th>Go</th><th>Java</th><th>Python</th></tr></thead><tbody><tr><td>依赖管理</td><td>go mod</td><td>Maven / Gradle</td><td>pip / poetry</td></tr><tr><td>主流 Web 框架</td><td>Gin / Echo / Fiber</td><td>Spring Boot</td><td>Django / FastAPI</td></tr><tr><td>ORM</td><td>GORM / sqlx</td><td>MyBatis / JPA</td><td>SQLAlchemy</td></tr><tr><td>测试</td><td>testing + go test</td><td>JUnit</td><td>pytest</td></tr><tr><td>构建产物</td><td>单二进制</td><td>jar / war</td><td>源码包</td></tr><tr><td>部署</td><td>Docker 直接跑</td><td>JDK + jar</td><td>解释器 + 依赖</td></tr></tbody></table><h3 id="_2-7-思想转变要点" tabindex="-1">2.7 思想转变要点 <a class="header-anchor" href="#_2-7-思想转变要点" aria-label="Permalink to &quot;2.7 思想转变要点&quot;">​</a></h3><table><thead><tr><th>Java / Python 习惯</th><th>Go 的正确姿势</th></tr></thead><tbody><tr><td>用异常控制业务错误</td><td>错误是返回值，每个边界显式处理</td></tr><tr><td>面向对象建模（继承体系）</td><td>结构体组合 + 小接口，为行为而非抽象编码</td></tr><tr><td>线程池 + Future 编排任务</td><td>goroutine + channel / WaitGroup，任务即协程</td></tr><tr><td>重度 ORM 模板与反射框架</td><td>接受&quot;薄框架&quot;，手写胶水代码换透明可控</td></tr><tr><td>虚拟机调优（GC、堆）</td><td>关注 goroutine 数与内存分配（pprof）</td></tr></tbody></table><hr><h2 id="三、版本与运行说明" tabindex="-1">三、版本与运行说明 <a class="header-anchor" href="#三、版本与运行说明" aria-label="Permalink to &quot;三、版本与运行说明&quot;">​</a></h2><h3 id="_3-1-推荐版本" tabindex="-1">3.1 推荐版本 <a class="header-anchor" href="#_3-1-推荐版本" aria-label="Permalink to &quot;3.1 推荐版本&quot;">​</a></h3><p>笔记示例基于 <strong>Go 1.22+</strong>（涉及 range 遍历整数、循环变量新语义、slices/maps 泛型包等 1.21/1.22 新特性），建议新项目直接使用当前最新稳定版。</p><h3 id="_3-2-验证环境" tabindex="-1">3.2 验证环境 <a class="header-anchor" href="#_3-2-验证环境" aria-label="Permalink to &quot;3.2 验证环境&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#B392F0;">go</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">version</span><span style="color:#E1E4E8;">          </span><span style="color:#6A737D;"># 确认已安装</span></span>
<span class="line"><span style="color:#B392F0;">go</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">env</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">GOPROXY</span><span style="color:#E1E4E8;">      </span><span style="color:#6A737D;"># 国内建议 https://goproxy.cn,direct</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#6F42C1;">go</span><span style="color:#24292E;"> </span><span style="color:#032F62;">version</span><span style="color:#24292E;">          </span><span style="color:#6A737D;"># 确认已安装</span></span>
<span class="line"><span style="color:#6F42C1;">go</span><span style="color:#24292E;"> </span><span style="color:#032F62;">env</span><span style="color:#24292E;"> </span><span style="color:#032F62;">GOPROXY</span><span style="color:#24292E;">      </span><span style="color:#6A737D;"># 国内建议 https://goproxy.cn,direct</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="_3-3-代码约定" tabindex="-1">3.3 代码约定 <a class="header-anchor" href="#_3-3-代码约定" aria-label="Permalink to &quot;3.3 代码约定&quot;">​</a></h3><ul><li>正文代码均为&quot;可运行风格&quot;片段：标注 <code>package main</code> 的可在空模块直接 <code>go run</code>；标注 <code>func</code> 的为节选，需按上下文补全 import 与调用。</li><li>涉及第三方库（gin、gorm、go-redis、zap 等）的版本以 <code>go get</code> 时的最新稳定版为准。</li></ul><hr><p>返回<a href="./../../">后端技术笔记目录</a>或继续阅读第一个模块：<a href="./Go-基础">Go 基础</a>。</p>`,37)]))}const u=d(r,[["render",n]]);export{b as __pageData,u as default};
